import{_ as d,C as n,o as h,c as i,j as t,a,E as o,a2 as c}from"./chunks/framework.TaNiW7i8.js";const _=JSON.parse('{"title":"Search the memory","description":"","frontmatter":{"title":"Search the memory"},"headers":[],"relativePath":"en/agent/chercher.md","filePath":"en/agent/chercher.md"}'),l={name:"en/agent/chercher.md"};function m(u,e,p,g,f,y){const r=n("AskExample"),s=n("Ask");return h(),i("div",null,[e[0]||(e[0]=t("h1",{id:"search-the-memory",tabindex:"-1"},[a("Search the memory "),t("a",{class:"header-anchor",href:"#search-the-memory","aria-label":'Permalink to "Search the memory"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("This journey finds a decision, a note, what the memory knows about a file, or the thread of the latest sessions. Everything here is "),t("strong",null,"read-only"),a(": no search writes to the memory (except adding aliases, flagged below).")],-1)),e[2]||(e[2]=t("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[a("What you ask the agent "),t("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),o(r,{tool:"mem_search"}),o(s,{say:"Search for “sealed” in the knowledge notes only, archives included.",verb:"mem_search",family:"rappel",args:'{"query":"seal","zone":"20-knowledge","include_archived":true}'}),o(r,{tool:"mem_about_path"}),o(s,{say:"Show me what is linked to the note 20-knowledge/runner, two levels deep.",verb:"mem_relations",family:"rappel",args:'{"path":"20-knowledge/runner","depth":2}'}),o(r,{tool:"mem_digest"}),o(s,{say:"Add the words “it stutters on phones” to the note 20-knowledge/runner.",verb:"mem_alias_add",family:"structure",args:'{"path":"20-knowledge/runner","aliases":["it stutters on phones"]}'}),e[3]||(e[3]=c('<p>A question about the past (&quot;what did we decide about…?&quot;, &quot;where did we talk about…?&quot;) is enough for the agent to search: the delivered procedures (see <a href="/Kessho/en/agent/connecter.html">Connect the agent</a>) invite it to.</p><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><ol><li><strong>Search for text.</strong> <a href="/Kessho/en/reference/mcp/rappel.html#mem-search"><code>mem_search</code></a> searches the whole vault and returns one match per line, with its context. The <code>query</code> pattern is a <strong>regular expression</strong>. The options, all optional: <ul><li><code>case_insensitive</code>: ignore case (on by default);</li><li><code>fold_accents</code>: &quot;reglage&quot; finds &quot;réglage&quot; (on by default);</li><li><code>fold_separators</code>: spaces, hyphens and underscores interchangeable, &quot;deploy kit&quot; finds <code>deploy-kit</code>; no effect if the pattern contains a regex metacharacter (on by default);</li><li><code>search_names</code>: the file <strong>name</strong> counts too, those matches carry <code>line_number</code> 0 (on by default);</li><li><code>zone</code>: restrict to one zone (<code>00-inbox</code>, <code>10-episodes</code>, <code>20-knowledge</code>…);</li><li><code>include_archived</code>: include <code>10-episodes/archived/</code>, excluded by default;</li><li><code>limit</code>: 50 matches by default, 500 at most.</li></ul></li><li><strong>Know what the memory knows about a file.</strong> <a href="/Kessho/en/reference/mcp/rappel.html#mem-about-path"><code>mem_about_path</code></a> takes the path of a file in the <strong>code repository</strong>, <strong>relative</strong> to its root (an absolute path is refused), and returns what the vault knows: the map facts describing it, the manifest that established its technology, the framing document that concerns it. The catalog asks for it to be called <strong>before</strong> touching a file you do not know. Knowing nothing is not an error: the answer then says how many notes cite any file at all.</li><li><strong>Follow a note&#39;s links.</strong> <a href="/Kessho/en/reference/mcp/rappel.html#mem-relations"><code>mem_relations</code></a> takes a note&#39;s path (relative to the vault, with or without <code>.md</code>) and returns what is more general (<code>up</code>), more specific (<code>down</code>) and neighbouring (<code>side</code>). <code>direction</code> is <code>up</code>, <code>down</code>, <code>side</code> or <code>all</code> (default); <code>depth</code> goes from 1 to 6 (default 2). Beyond 200 notes the result is marked truncated; links whose target does not exist are named.</li><li><strong>The thread of sessions.</strong> <a href="/Kessho/en/reference/mcp/rappel.html#mem-digest"><code>mem_digest</code></a> summarizes the <code>n</code> most recent archives of a project (5 by default, 50 at most): date, subject, excerpt. An archived project is only summarized with <code>from_archived: true</code>. To read a whole archive, see <a href="/Kessho/en/reference/mcp/rappel.html#mem-read-archive"><code>mem_read_archive</code></a> in <a href="/Kessho/en/agent/reprendre.html">Resume a project</a>.</li><li><strong>The whole graph.</strong> <a href="/Kessho/en/reference/mcp/rappel.html#mem-graph-export"><code>mem_graph_export</code></a> exports the notes and their relations; the payload is large, and <code>levels</code> keeps only the levels asked for (<code>domaine</code>, <code>concept</code>, <code>projet</code>, <code>note</code>, <code>archive</code>).</li><li><strong>Help find it again.</strong> <a href="/Kessho/en/reference/mcp/structure.html#mem-alias-add"><code>mem_alias_add</code></a> <strong>writes</strong>: it adds everyday-language aliases to a note (the symptom, the need) so it can be found with those words. Aliases already there are never lost.</li></ol><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>An agent search changes nothing on screen: the result is in your conversation with the agent. The application has its own ways to find a note: <strong>Search</strong> in the sidebar (see <a href="/Kessho/en/guide/home.html">Home</a>) and the <a href="/Kessho/en/guide/graph.html">graph</a>.</p><p>Only <code>mem_alias_add</code> writes: it lights up the freshness indicator like any agent write (see <a href="/Kessho/en/guide/zones.html">Zones</a>).</p>',6))])}const b=d(l,[["render",m]]);export{_ as __pageData,b as default};
